def transform(grid):
    # Extract the color that is constant at adjacent horizontal boundary markers;
    # retain a blank column between each independent vertical marker channel.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # Identify separator lines by their dominant color, at regular positions.
    row_sep = [r for r in range(h) if sum(v == background for v in grid[r]) <= w // 4]
    col_sep = [c for c in range(w) if sum(grid[r][c] == background for r in range(h)) <= h // 4]
    if len(row_sep) < 2 or len(col_sep) < 2:
        return [[background]]
    # Deduplicate nearby columns that carry identical marker sequences.
    cseq = [tuple(grid[r][c] for r in row_sep) for c in col_sep]
    cols = []
    for j, p in enumerate(cseq):
        if p == (row_sep and tuple([background] * len(row_sep))):
            continue
        if not cols or p != cols[-1]:
            cols.append(p)
    # Only marker channels whose values are not the line color are data.
    line_color = Counter(v for r in row_sep for v in grid[r]).most_common(1)[0][0]
    data = [p for p in cols if any(v != line_color for v in p)]
    # Compress duplicate tracks (the source encodes each channel twice).
    unique = []
    for p in data:
        if not unique or p != unique[-1]:
            unique.append(p)
    out = [[background] * max(1, 2 * len(unique) - 1) for _ in range(len(row_sep)-1)]
    for k, p in enumerate(unique):
        for i in range(len(row_sep)-1):
            if p[i] == p[i+1] and p[i] != line_color:
                out[i][2*k] = p[i]
    return out
